# وسوم أخطاء S2-U6: الوصف للوحة الكبار، وسؤالان موجِّهان لكل وسم (لا يكشفان الجواب)
import json
ROOT='/home/claude/waha-math'
E={
 "unitBig":("يختار وحدة أكبر مما يناسب الشيء",["لَوْ {قِسْتَ|قِسْتِ} بِهَذِهِ الوَحْدَةِ، هَلْ يَكُونُ العَدَدُ صَغِيرًا جِدًّا؟","هَلِ الشَّيْءُ أَقْصَرُ مِنْ وَحْدَةٍ وَاحِدَةٍ مِنْهَا؟"]),
 "unitSmall":("يختار وحدة أصغر مما يناسب الشيء",["لَوْ {قِسْتَ|قِسْتِ} بِهَذِهِ الوَحْدَةِ، هَلْ يَكُونُ العَدَدُ ضَخْمًا؟","كَمْ مَرَّةً {تَعُدُّ|تَعُدِّينَ} هَذِهِ الوَحْدَةَ عَلَى الشَّيْءِ؟"]),
 "tapeOff":("يخطئ قراءة شريط القياس",["أَيُّ عَدَدٍ مَكْتُوبٍ قَبْلَ الطَّرَفِ؟","كَمْ تَدْرِيجَةً بَعْدَهُ حَتَّى الطَّرَفِ؟"]),
 "mcSplit":("يخطئ كتابة الطول المركّب",["كَمْ مِئَةَ سَنْتِيمِتْرٍ فِي هَذَا الطُّولِ؟","كُلُّ مِئَةِ سَنْتِيمِتْرٍ مِتْرٌ: فَكَمْ يَبْقَى بَعْدَ الأَمْتَارِ؟"]),
 "convDir":("يضرب بدل أن يقسم أو العكس",["هَلِ الوَحْدَةُ الجَدِيدَةُ أَكْبَرُ أَمْ أَصْغَرُ؟","إِذَا صَغُرَتِ الوَحْدَةُ، هَلْ يَكْبُرُ العَدَدُ أَمْ يَصْغُرُ؟"]),
 "convFactor":("يخطئ العدد في التحويل (10 أو 100 أو 1000)",["كَمْ سَنْتِيمِتْرًا فِي المِتْرِ؟ وَكَمْ مِتْرًا فِي الكِيلُومِتْرِ؟","كَمْ مِلِّيمِتْرًا فِي السَّنْتِيمِتْرِ؟"]),
 "cmpDigits":("يقارن العددين وينسى الوحدتين",["هَلِ الطُّولَانِ بِوَحْدَةٍ وَاحِدَةٍ؟","كَمْ سَنْتِيمِتْرًا فِي هَذِهِ الأَمْتَارِ؟"]),
 "cmpOff":("يخطئ المقارنة بعد التحويل",["مَا الطُّولَانِ بِوَحْدَةٍ وَاحِدَةٍ؟","أَيُّ العَدَدَيْنِ أَكْبَرُ بَعْدَ التَّحْوِيلِ؟"]),
 "orderDigits":("يرتّب بالأعداد وينسى الوحدات",["هَلِ الأَطْوَالُ كُلُّهَا بِوَحْدَةٍ وَاحِدَةٍ؟","كَمْ سَنْتِيمِتْرًا فِي كُلِّ طُولٍ؟"]),
 "orderOff":("يخطئ ترتيب الأطوال",["أَيُّ الأَطْوَالِ أَقْصَرُ إِذَا {حَوَّلْتَهَا|حَوَّلْتِهَا} إِلَى وَحْدَةٍ وَاحِدَةٍ؟","هَلْ كُلُّ طُولٍ أَطْوَلُ مِمَّا قَبْلَهُ؟"]),
 "noRegroup":("لا يعيد التجميع: يترك 100 سم فأكثر",["كَمْ سَنْتِيمِتْرًا فِي المِتْرِ؟","هَلْ بَلَغَتِ السَّنْتِيمِتْرَاتُ مِئَةً؟"]),
 "lostCarry":("يحذف المتر الناتج من السنتيمترات",["أَيْنَ ذَهَبَتِ المِئَةُ سَنْتِيمِتْرٍ؟","هَلْ {نَقَلْتَ|نَقَلْتِ} المِتْرَ إِلَى عَمُودِ الأَمْتَارِ؟"]),
 "subBorrow":("يطرح الأصغر من الأكبر في عمود السنتيمترات بلا استلاف",["هَلْ يُطْرَحُ مِنَ العِشْرِينَ خَمْسُونَ؟","كَمْ سَنْتِيمِتْرًا فِي كُلِّ طُولٍ إِذَا {حَوَّلْتَهُ|حَوَّلْتِهِ}؟"]),
 "calcOff":("يخطئ جمع الأطوال أو طرحها",["هَلْ {جَمَعْتَ|جَمَعْتِ} السَّنْتِيمِتْرَاتِ وَحْدَهَا وَالأَمْتَارَ وَحْدَهَا؟","مَا المَجْمُوعُ بِالتَّقْرِيبِ لِأَقْرَبِ مِتْرٍ؟"]),
 "roundOff":("يخطئ التقريب لأقرب متر",["هَلِ السَّنْتِيمِتْرَاتُ أَقَلُّ مِنْ خَمْسِينَ أَمْ أَكْثَرُ؟","أَيُّ المِتْرَيْنِ أَقْرَبُ عَلَى الخَطِّ؟"]),
 "fenceOver":("يختار قطعاً مجموعها أطول من السور",["هَلْ زَادَ المَجْمُوعُ عَلَى طُولِ السُّورِ؟","أَيُّ قِطْعَةٍ لَوْ {أَبْعَدْتَهَا|أَبْعَدْتِهَا} يَقْرُبُ المَجْمُوعُ؟"]),
 "fenceShort":("يختار قطعاً مجموعها أقصر من السور",["كَمْ بَقِيَ مِنْ طُولِ السُّورِ؟","أَيُّ قِطْعَةٍ طُولُهَا قَرِيبٌ مِمَّا بَقِيَ؟"]),
 "estFar":("تقديره بعيد عن الطول المعقول",["{قَارِنْهُ|قَارِنِيهِ} بِمَرْجِعٍ: هَلْ هُوَ أَطْوَلُ مِنَ البَابِ أَمْ أَقْصَرُ؟","كَمْ إِصْبَعًا أَوْ قَلَمًا يَسَعُ؟"]),
 "trackSum":("مجموع المقاطع ليس 1000 م",["مَا مَجْمُوعُ المَقَاطِعِ الأَرْبَعَةِ؟","كَمْ مِتْرًا فِي الكِيلُومِتْرِ؟"]),
 "trackSame":("يكرّر طول مقطع",["هَلْ أَطْوَالُ المَقَاطِعِ كُلُّهَا مُخْتَلِفَةٌ؟","أَيُّ مَقْطَعَيْنِ لَهُمَا الطُّولُ نَفْسُهُ؟"]),
}
p=ROOT+'/content/errors.json'; raw=open(p,encoding='utf8').read(); e=json.loads(raw)
for k,(lab,qs) in E.items(): e[k]={"label":lab,"q":{f"gen.err.{k}.0{i+1}":q for i,q in enumerate(qs)}}
open(p,'w',encoding='utf8').write(json.dumps(e,ensure_ascii=False,indent=1)+('\n' if raw.endswith('\n') else ''))
print(len(E))
